const course: DeepCourse = {"slug":"seo-specialist","title":"SEO Specialist VA.","premium":true,"previewCount":3,"chunks":[{"kind":"html","value":"<section class=\"px-5 pt-28 md:px-8 md:pt-40\"><div class=\"mx-auto max-w-5xl\"><p class=\"eyebrow\">Specialism · Pro</p><h1 class=\"display-lg mt-4\">SEO Specialist VA<span class=\"dot\" aria-hidden=\"true\">.</span></h1><p class=\"lede mt-5 max-w-xl\">The highest-paying VA skill on the board, taught as diagnosis and evidence rather than keyword stuffing.</p><div class=\"mt-8\"><div class=\"flex flex-wrap items-center gap-2.5\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Premium course</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">9 modules</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">6h 39m of reading and doing</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">9 portfolio pieces</span></div><p class=\"mt-4 mb-2 text-[0.8125rem] text-muted\">Course content is based on active job listings and industry hiring patterns. These are practical guides, not formal certifications.</p></div></div></section><nav aria-label=\"Course sections\" class=\"sticky top-16 z-20 border-b border-line bg-paper/90 backdrop-blur-md\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-6xl\"><ul class=\"-mx-1 flex gap-1 overflow-x-auto py-2.5 [scrollbar-width:none] [&amp;::-webkit-scrollbar]:hidden\"><li><a href=\"#the-job\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">The job</a></li><li><a href=\"#tools\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Tools</a></li><li><a href=\"#modules\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Modules</a></li><li><a href=\"#rates\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Rates</a></li><li><a href=\"#first-client\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">First client</a></li><li><a href=\"#quiz\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Quiz</a></li><li><a href=\"#glossary\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Glossary</a></li><li><a href=\"#red-flags\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">Red flags</a></li><li><a href=\"#faq\" class=\"inline-flex whitespace-nowrap rounded-full px-3.5 py-1.5 text-[0.8125rem] font-medium text-muted transition-colors hover:bg-paper-3 hover:text-ink\">FAQ</a></li></ul></div></nav><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"the-job\" class=\"scroll-mt-32\"><div class=\"space-y-5\"><p class=\"text-[1.1875rem] leading-[1.7] text-ink\">SEO pays more than general admin for one unglamorous reason: it is measurable. A client can see whether the traffic went up. That cuts both ways, which is why the people who last in this work are the ones who can show their evidence.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">Most of the SEO work Filipino VAs actually get hired for is execution and reporting. Keyword research, content briefs, on-page fixes, crawls, citations, link prospecting, and the monthly report. That is a genuinely good place to be, because it is the part agencies are always short-staffed on.</p><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">You will work on one fictional client through the whole track: Baler Coffee Roasters, a small roaster in Quezon City with a WordPress site, 40 pages, and no idea why they rank for nothing. By the end you have an audit, a keyword map, a brief, a technical issue log, and a monthly report with your name on them.</p></div><dl class=\"mt-10 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Also posted as</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">SEO assistant, content SEO VA, link building assistant, SEO analyst (jr)</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Core loop</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Research → brief → implement → crawl → measure → report</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Pays more than general VA by</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Roughly 40–70% at the same experience level</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Hardest part</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">Saying &#x27;I don&#x27;t know yet&#x27; when a client wants a ranking promise</dd></div><div class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[11rem_1fr] sm:gap-6 sm:py-4\"><dt class=\"eyebrow pt-0.5 text-muted\">Easiest way in</dt><dd class=\"text-[0.9375rem] leading-relaxed text-ink\">A sandbox site you actually fixed, documented change by change</dd></div></dl></section><section class=\"mt-16\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What a shift actually looks like</h2><ol class=\"mt-6 space-y-0\"><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Start of shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Search Console check</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Coverage errors, manual actions, sudden impression drops. Two minutes unless something is on fire.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Morning block</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Keyword and SERP research</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">The deep-focus work. Do it while your brain is fresh, not at 4am.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Mid-shift</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">On-page implementation</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Titles, metas, headings, internal links, alt text. Log every change with a date.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Weekly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Crawl and issue triage</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">Screaming Frog run, then a prioritised sheet with evidence, not a 3,000-row dump.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span><span aria-hidden=\"true\" class=\"w-px flex-1 bg-line-2\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Weekly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">Content briefs</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">One to three per week for writers. This is where a lot of SEO VA hours go.</p></div></li><li class=\"relative flex gap-5 pb-6 last:pb-0\"><div class=\"flex flex-col items-center\"><span aria-hidden=\"true\" class=\"mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full border-2 border-teal bg-paper\"></span></div><div class=\"min-w-0 pb-1\"><p class=\"eyebrow text-clay\">Monthly</p><p class=\"mt-1 font-display text-[1.0625rem] font-semibold text-ink\">The report</p><p class=\"mt-1 text-[0.9375rem] leading-relaxed text-ink-2\">GSC and GA4 pulled, compared, and summarised into three recommendations.</p></div></li></ol></section></div><section id=\"tools\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">The tools, and why each one exists</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Do not buy anything yet. Learn the free ones properly and use the client&#x27;s licence for the rest — that is what everyone else is doing too.</p><div class=\"mt-8 space-y-8\"><div><p class=\"eyebrow text-muted\">Non-negotiable, and free</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Search Console</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The only data straight from Google. Queries, impressions, clicks, indexing, manual actions.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Analytics 4</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">What people did after they landed. Painful UI, learn it anyway.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Sheets</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Where every keyword map, issue log and report actually lives.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">PageSpeed Insights</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Core Web Vitals with field data. Read the field data, not the lab score.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Screaming Frog</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Site crawler. Free up to 500 URLs, which covers most small-business clients.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Looker Studio</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Connects GSC and GA4 into a dashboard the client will actually open.</p></li></ul></div><div><p class=\"eyebrow text-muted\">Paid tools you should understand even before you can afford them</p><ul class=\"mt-3.5 grid gap-3 sm:grid-cols-2\"><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Ahrefs</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Backlinks, keyword difficulty, content gap. Most agencies run it, so know the vocabulary.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Semrush</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The other one. Position tracking and site audit are the parts you will be asked to run.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Surfer / Clearscope / Frase</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">Paid</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Content optimisation scoring. Useful as a checklist, dangerous as a target.</p></li><li class=\"rounded-xl border border-line bg-card p-4 shadow-tile\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">WordPress + Yoast or RankMath</p><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Free tier</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Where you will make most on-page changes. Know how not to break a site.</p></li></ul></div></div></div></section>"},{"kind":"slot","value":"MODULES","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"keep-learning\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Keep learning<span class=\"dot\" aria-hidden=\"true\">.</span></h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Hand-picked and free. These open in a new tab — official docs, academies and channels that go deeper on what this track teaches. No affiliate links, no sign-up walls.</p><div class=\"mt-8\"><p class=\"eyebrow text-muted\">Watch first</p><div class=\"mt-3.5 grid gap-4 sm:grid-cols-2\"><div class=\"overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"aspect-video\"><iframe class=\"h-full w-full\" src=\"https://www.youtube-nocookie.com/embed/0eKVizvYSUQ\" title=\"How Google Search works (in 5 minutes)\" loading=\"lazy\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe></div><div class=\"px-4 py-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">How Google Search works (in 5 minutes)</p><p class=\"mt-0.5 text-[0.8125rem] text-muted\">Google Search Central · YouTube</p></div></div><div class=\"overflow-hidden rounded-2xl border border-line bg-card shadow-tile\"><div class=\"aspect-video\"><iframe class=\"h-full w-full\" src=\"https://www.youtube-nocookie.com/embed/xsVTqzratPs\" title=\"Complete SEO course for beginners\" loading=\"lazy\" allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\" referrerpolicy=\"strict-origin-when-cross-origin\" allowfullscreen></iframe></div><div class=\"px-4 py-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Complete SEO course for beginners</p><p class=\"mt-0.5 text-[0.8125rem] text-muted\">Ahrefs · YouTube</p></div></div></div></div><ul class=\"mt-8 grid gap-3 sm:grid-cols-2\"><li class=\"h-full\"><a href=\"https://developers.google.com/search/docs/fundamentals/seo-starter-guide\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google SEO Starter Guide</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The official baseline. If advice contradicts this, the advice is wrong.</p></a></li><li class=\"h-full\"><a href=\"https://moz.com/beginners-guide-to-seo\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Moz — Beginner’s Guide to SEO</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The classic long-form walkthrough, kept current.</p></a></li><li class=\"h-full\"><a href=\"https://www.youtube.com/@GoogleSearchCentral\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Search Central on YouTube</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Office hours and explainers straight from the Search team.</p></a></li><li class=\"h-full\"><a href=\"https://ahrefs.com/blog/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Ahrefs blog</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Data-backed studies. Great for lines you can quote in client reports.</p></a></li><li class=\"h-full\"><a href=\"https://support.google.com/business/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Business Profile help</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">The official manual for the local SEO work in module 9.</p></a></li><li class=\"h-full\"><a href=\"https://search.google.com/search-console/about\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"block h-full rounded-xl border border-line bg-card p-4 shadow-tile transition-colors hover:border-ink\"><div class=\"flex items-start justify-between gap-3\"><p class=\"font-display text-[0.9375rem] font-semibold text-ink\">Google Search Console</p><span aria-hidden=\"true\" class=\"text-[0.875rem] text-muted\">↗</span></div><p class=\"mt-2 text-[0.875rem] leading-relaxed text-ink-2\">Set it up on your own site today. Free, and every client will expect you to know it.</p></a></li></ul></section></div>"},{"kind":"html","value":"<section class=\"border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><section id=\"rates\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">What this actually pays</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">SEO local hourly ranges from OnlineJobs.ph&#x27;s April 2026 salary guide. A 2026 Outsource Accelerator guide puts many Philippine and Indian SEO VAs at $6–$15/hr. The spread depends almost entirely on whether you are gathering data or diagnosing and owning outcomes.</p><div class=\"mt-7 rounded-2xl border border-line bg-card p-6 shadow-tile sm:p-7\"><div class=\"space-y-7\"><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Beginner</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">4–6<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:28.57142857142857%;width:14.285714285714285%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Data gathering, uploads, citation cleanup, basic on-page under review.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 640–960/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Intermediate</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">7–10<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:50%;width:21.428571428571427%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Owns keyword research, briefs, crawls and the monthly report.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,120–1,600/mo full-time</p></div></div><div><div class=\"flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Expert</p><p class=\"font-display text-[1.0625rem] font-semibold tabular-nums text-teal-deep\">10–14<span class=\"text-[0.8125rem] font-medium text-muted\"> / hr</span></p></div><div class=\"relative mt-2.5 h-2.5 w-full overflow-hidden rounded-full bg-paper-3\"><div class=\"absolute inset-y-0 rounded-full bg-gradient-to-r from-teal-soft to-teal\" style=\"left:71.42857142857143%;width:28.57142857142857%\"></div></div><div class=\"mt-2 flex flex-wrap items-baseline justify-between gap-x-4 gap-y-0.5\"><p class=\"text-[0.8125rem] leading-relaxed text-muted\">Technical diagnosis, strategy, client-facing, accountable for outcomes.</p><p class=\"text-[0.75rem] tabular-nums text-muted-2\">≈ 1,600–2,240/mo full-time</p></div></div></div><p class=\"mt-7 border-t border-line pt-4 text-[0.75rem] leading-relaxed text-muted-2\">Directional market benchmarks, not a guarantee and not a ceiling. Source: <a href=\"https://blog.onlinejobs.ph/comprehensive-guide-to-virtual-assistant-salaries-in-the-philippines\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">OnlineJobs.ph salary guide, April 2026</a>. Monthly figures assume 40 hours a week, which most VA roles are not.</p></div><div class=\"mt-5 rounded-2xl border border-[#f4d9c6] bg-clay-wash/70 p-6 sm:p-7\"><p class=\"eyebrow text-clay-deep\">What actually moves you up a band</p><ul class=\"mt-3.5 grid gap-2.5 sm:grid-cols-2\"><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You can read a Screaming Frog crawl without a tutorial open</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You write briefs writers do not have to clarify</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You present to the client instead of the account manager presenting for you</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You can explain an algorithm update&#x27;s impact without panicking</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You have a documented case study with dated evidence</li><li class=\"flex gap-2.5 text-[0.9375rem] leading-relaxed text-ink-2\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2.5 w-2.5\" fill=\"currentColor\"><path d=\"M4 2.5 8.5 6 4 9.5z\"></path></svg></span>You have said no to a black-hat request in writing</li></ul></div></section></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><figure class=\"rounded-2xl border border-line bg-card p-7 shadow-card sm:p-9\"><figcaption class=\"flex flex-wrap items-center gap-3\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-clay-wash text-clay border-transparent\">Worker story</span><span class=\"text-[0.8125rem] text-muted\">One person&#x27;s experience, not a universal rule</span></figcaption><h2 class=\"mt-4 font-display text-[1.5rem] font-semibold leading-snug text-ink\">Fixed the site, emailed 20 businesses, got zero replies</h2><blockquote class=\"mt-5 border-l-2 border-clay pl-5 font-display text-[1.1875rem] italic leading-relaxed text-ink\">“PageSpeed 40 to 90, on-page cleaned, technical fixed. Twenty local businesses contacted. No reply.”</blockquote><p class=\"mt-5 text-[0.9375rem] leading-relaxed text-ink-2\">A beginner on r/digital_marketing built a sandbox site to learn on, genuinely improved it, then cold-emailed around 20 local businesses and heard nothing back. The thread&#x27;s useful advice was not &#x27;send more emails&#x27;. It was: build your own verifiable case study, help a friend or a non-profit with a defined project, and demonstrate a small result you can actually prove. One commenter added a sharp warning about people who present someone else&#x27;s results as their own.</p><div class=\"mt-5 rounded-xl border border-teal-pale bg-teal-wash/60 p-4\"><p class=\"eyebrow mb-1.5 text-teal-deep\">The lesson</p><p class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Cold email at low volume from an unknown name almost never works, and that is not a reflection of your skill. Warm routes convert: agencies needing implementation help, referrals from other VAs, and one real permissioned project you can talk about honestly.</p></div><a href=\"https://old.reddit.com/r/digital_marketing/comments/1ofxa4m/how_did_you_land_your_first_seo_client_when_you/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"mt-4 inline-block text-[0.8125rem] font-medium text-teal-deep underline decoration-teal-pale underline-offset-2 hover:text-ink\">Read the original thread — r/digital_marketing, 2026</a></figure></div><section id=\"first-client\" class=\"scroll-mt-32 border-y border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Getting the first one to say yes</h2><ol class=\"mt-7 space-y-4\"><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">01</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Build a sandbox and break it on purpose</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">A cheap domain, WordPress, GA4 and Search Console. Publish eight pages, then fix them one at a time and document every change. This is your laboratory and your portfolio at the same time.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">02</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Lead with an execution offer, not strategy</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">&#x27;I&#x27;ll clean up your technical issues and give you a prioritised log&#x27; or &#x27;I&#x27;ll build your keyword map and three briefs&#x27;. Defined, cheap to say yes to, and it is the work agencies are drowning in.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">03</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Pitch agencies before you pitch businesses</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">SEO agencies always need implementation hands and they already understand what you do. A business owner needs to be educated first, which is a much longer sale.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">04</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Do one non-profit or friend&#x27;s project properly</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">With permission and clear attribution. A real project with real GSC data is worth more than any mock, and it gives you your first honest &#x27;here is what happened&#x27; story.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">05</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Apply to the junior titles</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">SEO assistant, content SEO assistant, link building assistant, SEO VA. Do not wait until you feel like a specialist, or you never will.</p></div></li><li class=\"flex gap-4 rounded-2xl border border-line bg-card p-5 shadow-tile\"><span class=\"pt-0.5\"><span class=\"font-display text-sm font-extrabold tracking-[0.1em] text-accent\">06</span></span><div class=\"min-w-0\"><p class=\"font-display text-[1.0625rem] font-semibold text-ink\">Never claim someone else&#x27;s results</p><p class=\"mt-1.5 text-[0.9375rem] leading-relaxed text-ink-2\">It comes up in interviews constantly and the industry is small. Say &#x27;I did the implementation on this, the strategy was the lead&#x27;s&#x27; and you will be trusted more, not less.</p></div></li></ol><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">What goes in the portfolio</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">Every one of these comes out of the exercises above. Finish the track and you have the folder, not just the knowledge.</p><ul class=\"mt-5 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Keyword map with intent labels</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Shows you think in pages and priorities, not keyword lists.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Competitor gap analysis</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Proves you can find opportunity without being handed a brief.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Content brief</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">The single most requested SEO VA deliverable. Have one ready to show.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">On-page before and after with character counts</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Instantly legible to a non-technical client.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Screaming Frog issue log, prioritised</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Separates you from people who only know &#x27;content SEO&#x27;.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Local citation audit</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Easy first paid engagement for small businesses.</p></li><li class=\"grid gap-1 px-5 py-3.5 sm:grid-cols-[1fr_1.2fr] sm:gap-6\"><p class=\"text-[0.9375rem] font-semibold text-ink\">Monthly report + Looker Studio dashboard</p><p class=\"text-[0.875rem] leading-relaxed text-muted\">Reporting is what clients see. Being good at it makes you feel expensive.</p></li></ul></div></section>"},{"kind":"slot","value":"QUIZ","wrappers":[{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20"}]},{"kind":"html","value":""},{"kind":"slot","value":"GLOSSARY","wrappers":[{"tag":"section","class":"border-y border-line bg-paper-2/70 py-14 sm:py-20"},{"tag":"div","class":"mx-auto w-full px-5 sm:px-8 max-w-5xl"}]},{"kind":"html","value":"<div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-20\"><section id=\"red-flags\" class=\"scroll-mt-32\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Walk away when you see these</h2><p class=\"mt-2 max-w-2xl text-[0.9375rem] leading-relaxed text-ink-2\">Not every one of these is a scam. Some are just clients who will cost you more than they pay you, which ends the same way.</p><ul class=\"mt-7 space-y-3\"><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Guaranteed #1 rankings promised to the end client</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Nobody can promise this. If the agency sells it, you will be blamed when it does not happen.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Buy 5,000 backlinks / PBN packages</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Cheap link schemes get sites penalised. You cannot un-ring that bell for a small business.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Write fake reviews or incentivised reviews</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Against platform policy, illegal in some markets, and a reputational risk to you personally.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Spun or plagiarised content</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">It will be found, and your name is on the upload log.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Hide changes from the site owner</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">If a client asks you to conceal work from the person who owns the site, leave.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Access with no backup or staging</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">One bad plugin update and you are the person who broke a live business at 3am.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Blames you for every ranking fluctuation</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">Rankings move daily. A client who does not accept that will never be satisfied.</p></li><li class=\"rounded-xl border border-[#f0d5cd] bg-clay-wash/60 p-4 sm:p-5\"><p class=\"flex gap-2.5 font-display text-[1rem] font-semibold text-ink\"><span class=\"mt-1.5 shrink-0 text-clay\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-3 w-3\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M3 3l6 6M9 3l-6 6\"></path></svg></span>Full strategy, content, links and reporting at a general-VA rate</p><p class=\"mt-1.5 pl-6 text-[0.875rem] leading-relaxed text-ink-2\">That is four jobs. Quote them separately or decline.</p></li></ul></section></div><section id=\"faq\" class=\"scroll-mt-32 border-t border-line bg-paper-2/70 py-14 sm:py-20\"><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl\"><h2 class=\"font-display text-[1.75rem] font-semibold text-ink\">Questions people actually ask</h2><div class=\"mt-7 divide-y divide-line overflow-hidden rounded-2xl border border-line bg-card\"><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Can I learn SEO without paying for Ahrefs or Semrush?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Yes, and most beginners should. Search Console, GA4, Keyword Planner, Screaming Frog&#x27;s free tier, PageSpeed Insights and Looker Studio cover the real work. Learn the paid tools&#x27; vocabulary so you can talk about them, then use the client&#x27;s licence when you are hired.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">How long until an SEO change shows results?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Technical fixes can move within days. Content and links usually take six to twelve weeks, sometimes longer on a weak domain. Say that up front, because a client who expects two weeks will fire you in week three regardless of what you did.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Is AI writing going to kill SEO VA work?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">It killed the cheap end of it. Nobody pays for a VA to paste a prompt result. What is still in demand: knowing what to build, checking whether it is true, doing the technical implementation, and being accountable for the reporting. Aim there.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">What if I break the client&#x27;s site?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">Tell them immediately, revert if you can, and never work without a backup or a staging copy again. Also refuse access arrangements where you are the only safety net. That refusal is a senior move, not a nervous one.</p></details><details class=\"group\"><summary class=\"flex cursor-pointer list-none items-center gap-4 px-5 py-4 text-[0.9375rem] font-semibold text-ink hover:bg-paper-2/70 [&amp;::-webkit-details-marker]:hidden\">Do I need to know how to code?<span aria-hidden=\"true\" class=\"ml-auto shrink-0 text-muted transition-transform duration-200 group-open:rotate-45\">+</span></summary><p class=\"px-5 pb-5 text-[0.9375rem] leading-relaxed text-ink-2\">No, but knowing basic HTML, what a redirect is, and how to read a page&#x27;s source will move you up a rate band faster than almost anything else on this list.</p></details></div><h3 class=\"mt-14 font-display text-[1.35rem] font-semibold text-ink\">Where the facts in this course came from</h3><p class=\"mt-2 text-[0.9375rem] leading-relaxed text-ink-2\">All free, all worth your time. Open them in another tab and check us.</p><ul class=\"mt-5 space-y-2.5\"><li><a href=\"https://ahrefs.com/academy/ahrefs-youtube\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Ahrefs Academy on YouTube</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">28 lessons, about five hours, genuinely free. The best structured beginner SEO course available.</span></a></li><li><a href=\"https://ahrefs.com/academy/ahrefs-youtube/keyword-research\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Ahrefs keyword research tutorial</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Watch this before module 2. It will make the exercise much faster.</span></a></li><li><a href=\"https://ahrefs.com/blog/seo-job-description/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Ahrefs SEO job description breakdown</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">What employers actually list. Use it to reverse-engineer your own skills list.</span></a></li><li><a href=\"https://seovisibility.co/seo-virtual-assistant-explained/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">SEO VA role explained</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Straightforward description of the tasks agencies outsource.</span></a></li><li><a href=\"https://www.outsourceaccelerator.com/glossary/seo-virtual-assistant/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">Outsource Accelerator SEO VA rates</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">Second rate benchmark, more international. Cross-check against the OLJ guide.</span></a></li><li><a href=\"https://old.reddit.com/r/digital_marketing/comments/1ofxa4m/how_did_you_land_your_first_seo_client_when_you/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"group flex flex-wrap items-baseline gap-x-3 gap-y-1 rounded-xl border border-line bg-card px-4 py-3 shadow-tile transition-colors hover:border-teal-pale\"><span class=\"text-[0.9375rem] font-semibold text-ink group-hover:text-teal-deep\">r/digital_marketing first client thread</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-leaf-wash text-leaf border-transparent\">Free</span><span class=\"w-full text-[0.875rem] leading-relaxed text-muted\">The worker story in this course. Read the comments, not just the post.</span></a></li></ul></div></section><div class=\"mx-auto w-full px-5 sm:px-8 max-w-5xl py-14 sm:py-16\"><div class=\"rounded-2xl border border-line bg-clay-wash/60 p-7 sm:p-9\"><h2 class=\"font-display text-[1.5rem] font-semibold text-ink\">Finished? Go and use it.</h2><p class=\"mt-3 max-w-lg text-[0.9375rem] leading-relaxed text-ink-2\">The board updates every 30 minutes. Filter for this specialism, check your number against the rate tool, and send five tailored applications rather than fifty copy-pasted ones.</p><div class=\"mt-6 flex flex-wrap gap-3\"><a class=\"btn btn-primary\" href=\"/jobs\">See jobs on the board</a><a class=\"btn btn-ghost\" href=\"/pricing-tool\">Check your rate</a></div></div><div class=\"mt-10\"><p class=\"eyebrow text-muted\">Other written tracks</p><ul class=\"mt-3 flex flex-wrap gap-2.5\"><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/executive-assistant\">Executive Assistant</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/social-media-manager\">Social Media Manager VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/real-estate-va\">Real Estate VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/ecommerce-va\">E-commerce VA</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/complete-va-starter\">The Complete VA Starter</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/applications-that-get-replies\">Applications That Get Replies</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/pricing-and-negotiation\">Pricing &amp; Negotiation</a></li><li><a class=\"inline-flex rounded-full border border-line-2 bg-card px-4 py-2 text-[0.875rem] font-medium text-ink-2 transition-colors hover:border-teal-pale hover:text-teal-deep\" href=\"/courses/becoming-an-ops-lead\">Becoming an Operations Lead</a></li></ul></div><a class=\"btn btn-ghost mt-8\" href=\"/courses\">← All courses</a></div><!--$--><!--/$-->"}],"modules":[{"n":1,"title":"How search actually works","outcome":"You can explain crawling, indexing and ranking to a client, and explain why nobody can guarantee a #1 spot.","badges":["Rates","Red/green flags"],"minutes":26,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Three separate stages. Crawling is Google finding the page, indexing is Google storing it, ranking is Google choosing it. A page can be crawled and never indexed, and that is the most common problem you will find.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Blocking a page in robots.txt stops crawling, not indexing. If you want a page out of the index you use a noindex tag and let Google crawl it to see the tag. Blocking it in robots.txt actually prevents the removal.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Search intent is the whole game. &#x27;Coffee beans&#x27; wants shops, &#x27;how to store coffee beans&#x27; wants an article, &#x27;baler coffee roasters&#x27; wants that specific business. Serving the wrong format loses no matter how good the writing is.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The way to find intent is to look at the SERP, not to theorise. Open the search, look at what is ranking, and match that format.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Domain Rating and Domain Authority are third-party guesses, not Google numbers. Useful for comparison, embarrassing to present as fact.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Anyone promising a guaranteed ranking is either lying or planning to rank you for something nobody searches.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — One keyword, three intents</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&#x27;espresso machine&#x27; → SERP is all shopping listings and category pages. Intent: buy. A blog post will never rank here.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&#x27;espresso machine vs drip&#x27; → SERP is comparison articles and a video. Intent: research. This is your blog post.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&#x27;espresso machine repair quezon city&#x27; → SERP is a map pack and three local sites. Intent: local service. This needs a Business Profile, not an article.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Before writing a single word, search the term and screenshot the top five. That screenshot is your brief&#x27;s first slide, and it ends most arguments with clients.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What SEO work pays a Filipino freelancer</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">SEO is one of the few VA-adjacent skills where the ceiling is genuinely high, because results are measurable. The gap between the entry and lead row is almost entirely &#x27;can you tie your work to revenue&#x27;.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Entry (0–1 yr)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$4–6</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$650–1,000</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Keyword lists, meta tags, uploading posts. Someone else decides strategy.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Junior (1–2 yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$6–9</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,000–1,450</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You run audits and briefs. You can explain why a page isn&#x27;t ranking.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Mid (2–4 yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$9–13</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$1,450–2,100</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own a content calendar and a technical backlog. You brief writers and devs.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Senior (4–6 yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$13–18</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,100–2,900</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You own traffic targets. You can defend a strategy to a sceptical founder.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Lead / strategist (6+ yrs)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$18–30</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$2,900–4,800</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">You tie rankings to pipeline and revenue. You manage other SEOs.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><div class=\"mt-4\"><p class=\"eyebrow mb-2 text-muted\">Same skill, different client</p><ul class=\"grid gap-2 sm:grid-cols-2\"><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Verse&#x27;s job board (median)</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$7.30</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Across live SEO listings. Higher than the general VA median of $3.50 — the specialism pays.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">US agency, white-label</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$8–15</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Steady volume, less client drama, but you never own the relationship.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">US client, direct</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$12–25</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Where the money is. You need to be able to run a call without a manager.</p></li><li class=\"rounded-lg border border-line bg-card px-3 py-2.5\"><div class=\"flex items-baseline justify-between gap-3\"><span class=\"text-[0.8125rem] font-semibold text-ink\">Local PH SME</span><span class=\"text-[0.8125rem] font-bold tabular-nums text-teal-deep\">$3–6</span></div><p class=\"mt-1 text-[0.75rem] leading-snug text-muted\">Good for a first case study, bad as a career. Take one, then move up.</p></li></ul></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sources: Verse&#x27;s live board (n=2,081 listings), OnlineJobs.ph SEO expectations ($4.20–11.20+), and 2026 agency rate cards quoting $9–16/hr for specialists.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A prospect asks about results</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Yes, we can guarantee you&#x27;ll rank #1 on Google for your main keyword within 3 months, or your money back.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Nobody can guarantee a ranking, because nobody controls the algorithm or the competitors. Anyone who promises this is either lying or planning to rank you for a keyword nobody searches.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;I can&#x27;t promise a position — nobody can, and anyone who does is selling you something. What I can commit to is: a full technical audit in week 2, 8 pages of new content a month, and a monthly report showing exactly which pages moved and what I&#x27;m doing next. If clicks haven&#x27;t moved in 6 months, fire me.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Honest about what&#x27;s controllable, specific about deliverables, and puts a real check-in on the table. This wins more clients than the guarantee does.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Explaining why traffic dropped</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;There was probably a Google algorithm update. It happens sometimes, we just have to wait it out.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">This is the SEO equivalent of a shrug. Sometimes it&#x27;s true, but if you can&#x27;t tell the difference between an update, a tracking break, a seasonal dip and a self-inflicted technical error, you&#x27;re not doing the job.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Clicks dropped 22% starting March 12. Three things I checked: (1) no core update was confirmed on that date, (2) GA4 tracking is still firing, (3) Search Console shows 340 pages moved to &#x27;crawled, not indexed&#x27; on March 11 — which lines up with the site migration your dev did. I think it&#x27;s the migration. Here&#x27;s the fix and it&#x27;ll take a week.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">You ruled things out in order, named a date, found a cause, and proposed a fix. That&#x27;s diagnosis, not weather commentary.</p></div></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Pick five search terms in any niche you know. Search each one, screenshot the top five results, and label the intent and the winning content format.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A five-row intent table with a screenshot and a format verdict per row.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 35 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every row names the dominant content format, not just a category label</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You noted whether there is a map pack, shopping row, or featured snippet</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least one of your original guesses turned out to be wrong, and you wrote that down</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You used an incognito window</span></label></li></ul></div>"},{"n":2,"title":"Keyword research that produces a plan","outcome":"You can turn a business into a keyword map that tells someone exactly what to publish next.","badges":["Workflow","Tools","2 templates"],"minutes":40,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Start from the business, not the tool. List their services, their products, the questions customers ask on the phone, and the words competitors use.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Expand the seed list with Keyword Planner, Google autocomplete, People Also Ask, and the related searches at the bottom of the page. All free.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Cluster by intent, not by string similarity. &#x27;Best flat white in QC&#x27; and &#x27;flat white near me&#x27; are one page. &#x27;What is a flat white&#x27; is a different page entirely.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One primary term per page. If two pages target the same term you get keyword cannibalisation and Google picks the wrong one, usually the weaker one.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Volume is an estimate and difficulty is a vendor&#x27;s opinion. Write them down with the source and date, then decide with the SERP.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Deliver a content map, never a raw keyword list. Columns: URL, primary term, secondary terms, intent, current position, format, priority, status.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Baler Coffee Roasters, five rows of a real map</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">/  → &#x27;specialty coffee roaster quezon city&#x27; · local · exists, pos 18 · homepage · P1</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">/shop/single-origin → &#x27;single origin coffee beans philippines&#x27; · transactional · not ranking · category · P1</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">/blog/store-coffee-beans → &#x27;how to store coffee beans philippines&#x27; · informational · none · 900-word guide · P2</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">/blog/flat-white-vs-latte → &#x27;flat white vs latte&#x27; · informational · none · comparison + table · P3</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">/wholesale → &#x27;wholesale coffee supplier manila&#x27; · commercial · none · service page + form · P1</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Five rows and the client already knows what to build first. A 400-keyword export tells them nothing and quietly signals you do not know how to prioritise.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Keyword research that ends in a publishing plan</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">New client, or a quarterly content refresh. Budget half a day.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write down what the business actually sells, in their words</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Before touching a tool. If you can&#x27;t explain what they charge for, you&#x27;ll build a keyword list for the wrong company.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Seed 10–20 obvious terms by hand</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">From their homepage, their sales calls, and the questions they get asked. Tools expand seeds, they don&#x27;t invent them.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Expand with a tool and pull the real numbers</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Volume, difficulty, and crucially the SERP — who currently ranks. If page one is all Reddit and Quora, that&#x27;s an opportunity. If it&#x27;s all Amazon and Wikipedia, walk away.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Sort by intent, not by volume</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Informational, commercial, transactional, navigational. A 90-volume transactional term beats a 9,000-volume informational one for a small business.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Cluster into pages, not keywords</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">One page can rank for 30 variants. &quot;best coffee beans manila&quot;, &quot;where to buy coffee beans manila&quot; and &quot;manila coffee bean shop&quot; are one page, not three.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Assign each cluster a page type and a status</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">New post / update existing / merge two thin pages / do nothing. The &#x27;do nothing&#x27; column is what makes this a plan instead of a wish list.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Handing over a 2,000-row spreadsheet. Nobody reads it, nothing gets published, and you look like you did a lot of work that changed nothing. Ship 20 clustered rows with a publish order instead.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Keyword and SEO research tools</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">You do not need a $200/month tool to get hired. You need to know what the numbers mean. Start free, and let a client pay for the paid one.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Google Search Console</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">What a site ALREADY ranks for. The only source of true data.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy — but takes months to read well</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The most underrated tool in SEO. Every other tool estimates; this one measures. Learn the Queries and Pages reports cold.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Google Keyword Planner</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Volume ranges straight from Google.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free (needs an Ads account)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Ranges are vague without ad spend, but it&#x27;s free and it&#x27;s the source everyone else resells.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Ahrefs</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Backlinks, competitor gaps, accurate difficulty scores.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — a week to get useful</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$129/mo (free Webmaster Tools tier)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The industry standard. Use the free Webmaster Tools tier on your own site to learn the UI before a client pays for a seat.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Semrush</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">All-in-one, and the name most US clients recognise.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — cluttered UI</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">$140/mo (limited free tier)</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">If a client already has a seat, use theirs. Listing it on your CV opens doors even if you prefer Ahrefs.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">AnswerThePublic / AlsoAsked</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Real questions people ask. Great for FAQ sections and AI citations.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free tier</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Cheap way to find long-tail intent. Increasingly important now that AI answers pull from question-shaped content.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Screaming Frog</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Crawling a site for technical problems.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — looks scary, isn&#x27;t</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free up to 500 URLs</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Free tier covers most small business sites entirely. Learning this one thing puts you ahead of most VAs applying for SEO roles.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Keyword map (the deliverable, not the raw list)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One row per PAGE, not per keyword. This is what you hand a client. Build it in Sheets.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Target page</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Primary keyword</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Vol</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">KD</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Intent</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Also ranks for</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Action</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Priority</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Owner</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Due</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">/coffee-beans-manila</td><td class=\"px-3 py-2.5 text-ink-2\">buy coffee beans manila</td><td class=\"px-3 py-2.5 text-ink-2\">320</td><td class=\"px-3 py-2.5 text-ink-2\">12</td><td class=\"px-3 py-2.5 text-ink-2\">Transactional</td><td class=\"px-3 py-2.5 text-ink-2\">where to buy coffee beans manila; manila coffee bean shop; coffee beans delivery manila</td><td class=\"px-3 py-2.5 text-ink-2\">NEW page</td><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">Writer</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 14</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">/blog/how-to-store-beans</td><td class=\"px-3 py-2.5 text-ink-2\">how to store coffee beans</td><td class=\"px-3 py-2.5 text-ink-2\">1,900</td><td class=\"px-3 py-2.5 text-ink-2\">8</td><td class=\"px-3 py-2.5 text-ink-2\">Informational</td><td class=\"px-3 py-2.5 text-ink-2\">coffee bean storage; keep beans fresh</td><td class=\"px-3 py-2.5 text-ink-2\">UPDATE — add FAQ + schema</td><td class=\"px-3 py-2.5 text-ink-2\">2</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 18</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">/blog/beans-101 + /blog/bean-guide</td><td class=\"px-3 py-2.5 text-ink-2\">coffee bean types</td><td class=\"px-3 py-2.5 text-ink-2\">880</td><td class=\"px-3 py-2.5 text-ink-2\">15</td><td class=\"px-3 py-2.5 text-ink-2\">Informational</td><td class=\"px-3 py-2.5 text-ink-2\">—</td><td class=\"px-3 py-2.5 text-ink-2\">MERGE into one, redirect old</td><td class=\"px-3 py-2.5 text-ink-2\">3</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 21</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">/wholesale</td><td class=\"px-3 py-2.5 text-ink-2\">wholesale coffee supplier philippines</td><td class=\"px-3 py-2.5 text-ink-2\">140</td><td class=\"px-3 py-2.5 text-ink-2\">22</td><td class=\"px-3 py-2.5 text-ink-2\">Commercial</td><td class=\"px-3 py-2.5 text-ink-2\">bulk coffee supplier ph</td><td class=\"px-3 py-2.5 text-ink-2\">NEW page</td><td class=\"px-3 py-2.5 text-ink-2\">4</td><td class=\"px-3 py-2.5 text-ink-2\">Writer</td><td class=\"px-3 py-2.5 text-ink-2\">Mar 28</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">Notes column rules:\n• Priority 1 = transactional + low KD + we have no page. Always do these first.\n• Never more than 8 rows in one month&#x27;s plan. A plan nobody finishes is not a plan.</pre></div></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Client kickoff questions (before any research)</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Send before your first SEO call. The answers decide the entire keyword strategy.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Before I start research, six questions:\n\n1. What do you sell, and which one makes you the most money?\n2. Who&#x27;s your ideal customer, and where are they? (City? Country? Whole world?)\n3. Name 3 competitors you&#x27;d hate to lose a deal to.\n4. What do customers say when they describe your product to a friend?\n5. What&#x27;s the one page on your site you most want people to land on?\n6. What have you already tried, and what happened?\n\nAccess I&#x27;ll need (view is fine to start):\n• Google Search Console\n• Google Analytics 4\n• The CMS (WordPress / Shopify / Webflow — read-only first)\n• Google Business Profile, if you have a physical location\n\nIf you don&#x27;t have Search Console set up, tell me and I&#x27;ll do it — takes 10 minutes and it&#x27;s the single most useful thing we can turn on.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Build a 20-row keyword map for a real local business near you. Use only free tools. Mark each row with intent, format and priority.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A Google Sheet keyword map with the eight columns above and a one-paragraph &#x27;build these three first&#x27; note.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 90 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No two rows target the same primary term</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every row has an intent label backed by a SERP you actually looked at</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Volume and difficulty cells note their source and the date pulled</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Priorities are justified in the note, not just assigned</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least three rows are pages that do not exist yet</span></label></li></ul></div>"},{"n":3,"title":"On-page SEO without keyword stuffing","outcome":"You can improve a page&#x27;s title, structure and links so it reads better for humans and clearer for crawlers.","badges":["Time split","Red/green flags","1 template"],"minutes":34,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The title tag is the highest-leverage 60 characters on the page. Primary term near the front, then the differentiator, then the brand.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Meta descriptions do not rank you, they win the click. Write them as ad copy and stay near 150 characters.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One H1 per page, and headings that describe the section honestly. H2s that are just keywords make the page unreadable and rarely help.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Internal links are the most underused lever in SEO. Link from your strong existing pages into the new one with descriptive anchor text, not &#x27;click here&#x27;.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Alt text describes the image for someone who cannot see it. If a keyword fits naturally, fine. If not, leave it out.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Keyword stuffing has not worked in over a decade and now actively hurts. Cover the topic properly and the terms show up on their own.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Log every change with a date. When traffic moves in six weeks, the change log is the only way anyone knows why.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — One page, rewritten</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Title: Home | Baler Coffee Roasters | Coffee QC | Best Coffee | Buy Coffee Beans Online Philippines</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">H1: Welcome to our website</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Meta: Baler Coffee Roasters. Coffee. Beans. Quezon City. Order now.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Intro: We are a company that sells coffee. Our coffee is the best coffee in the Philippines for coffee lovers who love coffee.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Internal links: none</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Alt text: IMG_2841.jpg</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Title: Specialty Coffee Roaster in Quezon City — Baler Coffee Roasters (58 chars)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">H1: Small-batch coffee, roasted in Quezon City every Tuesday</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Meta: Single-origin beans roasted weekly in QC. Free Metro Manila delivery over ₱1,500. Wholesale enquiries welcome. (146 chars)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Intro: We roast single-origin beans in small batches every Tuesday and ship them within 48 hours, so what arrives is a week old, not a year.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Internal links: 4 added — to /shop/single-origin, /wholesale, /blog/store-coffee-beans, /visit</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Alt text: Green Benguet beans in a drum roaster mid-first-crack</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The &#x27;after&#x27; mentions coffee less and will rank better. Specificity, dates, prices and places are what make a page look like a real business to both readers and machines.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Where the hours go</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Where an SEO retainer&#x27;s hours actually go</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A 20 hr/week retainer for one small business client. Notice how little of it is &#x27;doing SEO&#x27; in the way beginners imagine.</p><div class=\"mt-4\"><div class=\"flex flex-col items-center gap-5 sm:flex-row sm:items-start sm:gap-7\"><svg viewBox=\"0 0 140 140\" class=\"h-[8.5rem] w-[8.5rem] shrink-0 -rotate-90\" role=\"img\" aria-labelledby=\"_R_b3lanpfiuqbtb_\"><title id=\"_R_b3lanpfiuqbtb_\">Content: briefs, editing, publishing 35%, On-page fixes and internal linking 18%, Reporting and client comms 15%, Technical: crawls, fixes, monitoring 12%, Research: keywords, competitors, SERPs 12%, Link prospecting and outreach 8%</title><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"var(--color-line)\" stroke-width=\"20\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#097769\" stroke-width=\"20\" stroke-dasharray=\"123.15043202071988 228.70794518133695\" stroke-dashoffset=\"0\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#5fd0bf\" stroke-width=\"20\" stroke-dasharray=\"63.334507896370226 288.5238693056866\" stroke-dashoffset=\"-123.15043202071988\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#4453b8\" stroke-width=\"20\" stroke-dasharray=\"52.778756580308524 299.0796206217483\" stroke-dashoffset=\"-186.48493991709012\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#075f55\" stroke-width=\"20\" stroke-dasharray=\"42.223005264246815 309.63537193781\" stroke-dashoffset=\"-239.26369649739866\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#c3e6df\" stroke-width=\"20\" stroke-dasharray=\"42.223005264246815 309.63537193781\" stroke-dashoffset=\"-281.48670176164546\"></circle><circle cx=\"70\" cy=\"70\" r=\"56\" fill=\"none\" stroke=\"#e07a2f\" stroke-width=\"20\" stroke-dasharray=\"28.148670176164547 323.70970702589227\" stroke-dashoffset=\"-323.70970702589227\"></circle></svg><ul class=\"w-full space-y-2\"><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#097769\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Content: briefs, editing, publishing</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">35%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">The biggest block by far. SEO is mostly a publishing operation.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#5fd0bf\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">On-page fixes and internal linking</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">18%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Titles, headings, links, images. Unglamorous, high return.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#4453b8\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Reporting and client comms</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">15%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">If you skip this you get fired even when the work is good.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#075f55\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Technical: crawls, fixes, monitoring</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">12%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Front-loaded. Heavy in month one, light after.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#c3e6df\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Research: keywords, competitors, SERPs</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">12%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Feels like the main job. Is roughly a tenth of it.</p></li><li><div class=\"flex items-baseline gap-2.5\"><span aria-hidden=\"true\" class=\"mt-[0.3rem] h-2.5 w-2.5 shrink-0 rounded-[3px]\" style=\"background:#e07a2f\"></span><span class=\"flex-1 text-[0.875rem] font-medium leading-snug text-ink\">Link prospecting and outreach</span><span class=\"shrink-0 text-[0.875rem] font-bold tabular-nums text-ink\">8%</span></div><p class=\"ml-[1.25rem] mt-0.5 text-[0.75rem] leading-snug text-muted\">Low hours, low hit rate, occasionally huge payoff.</p></li></ul></div><p class=\"mt-4 border-t border-line pt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Half your week is making and fixing pages. If you want to charge senior rates, get fast at the content pipeline — that&#x27;s where the leverage is.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Writing a title tag</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Coffee Beans Manila | Buy Coffee Beans Manila | Best Coffee Beans Manila Philippines | Cheap Coffee Beans&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Keyword stuffed, over 60 characters so Google will rewrite it anyway, and it reads like spam. A human seeing this in the results scrolls past.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Fresh Coffee Beans in Manila — Roasted Weekly, Same-Day Delivery&quot; (63 chars)</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Contains the keyword naturally, adds two reasons to click that competitors don&#x27;t have, and reads like a real business wrote it. Click-through rate is a ranking input; boring titles cost you twice.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A client asks you to &#x27;add the keyword more times&#x27;</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Going through the page and swapping every &quot;it&quot; and &quot;our beans&quot; for &quot;coffee beans manila&quot; until the density hits 3%.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Keyword density stopped being a thing over a decade ago. You will make the page worse for readers, and Google&#x27;s helpful content systems specifically target this.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Density isn&#x27;t a ranking factor any more — Google matches meaning, not counts. What&#x27;ll actually move this page: the H1 doesn&#x27;t mention Manila, there&#x27;s no mention of delivery areas, and the three competitors ranking above us all have a price on the page. Can I add those instead? I&#x27;ll keep the keyword in the title, H1 and first paragraph, which is all it needs.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">You said no with a reason, then immediately offered something better and more specific. Clients accept &#x27;no&#x27; far more easily when it comes attached to a &#x27;here&#x27;s what instead&#x27;.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">On-page optimisation checklist</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Run down this list for every page you touch. Takes 15 minutes once you know it.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>PAGE: [url]\nTarget: [primary keyword] | Intent: [informational/commercial/transactional]\n\nTITLE + META\n[ ] Title under 60 chars, keyword near the front, one reason to click\n[ ] Meta description 140–160 chars — it&#x27;s not a ranking factor, it IS a click factor\n[ ] URL slug short, lowercase, hyphens, no dates, no stop words\n\nSTRUCTURE\n[ ] Exactly one H1, contains the keyword or a close variant\n[ ] H2s answer the questions in &quot;People also ask&quot; for this term\n[ ] No heading levels skipped (H2 → H4 is a fail)\n[ ] First 100 words state plainly what the page is and who it&#x27;s for\n\nCONTENT\n[ ] Answers the query in the first paragraph — don&#x27;t make people scroll for it\n[ ] Covers the subtopics the top 3 results all cover (and one they don&#x27;t)\n[ ] Specific: real numbers, prices, dates, place names\n[ ] Reads out loud without embarrassment\n\nLINKS\n[ ] 2–4 internal links OUT to relevant pages, descriptive anchor text\n[ ] At least 1 internal link IN from an existing relevant page — this is the step everyone forgets\n[ ] External links open where the client expects, and point somewhere credible\n\nMEDIA\n[ ] Images compressed (under 200kb), descriptive filenames, real alt text\n[ ] Nothing above the fold that takes over 2.5s to load\n\nTECHNICAL\n[ ] Indexable (no stray noindex), canonical points to itself\n[ ] Schema added if it fits: Article, FAQ, Product, LocalBusiness\n[ ] Mobile: tap targets not cramped, no horizontal scroll</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Find a genuinely bad local business page. Rewrite the title, meta, H1, intro paragraph, and propose five internal links with anchor text.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A before-and-after doc with character counts and a one-line reason for each change.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 50 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Title is under 60 characters and reads like a sentence</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Meta is 140–155 characters and contains a reason to click</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The intro says something specific a competitor could not copy-paste</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Anchor text is descriptive, never &#x27;click here&#x27; or &#x27;read more&#x27;</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No sentence contains the primary keyword more than once</span></label></li></ul></div>"},{"n":4,"title":"Content briefs writers can actually use","outcome":"You can hand a writer a brief that produces the right article on the first attempt.","badges":["Workflow","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A brief is a decision document. Target query, intent, audience, angle, outline, entities to cover, internal links, references, and what not to claim.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Include the top three ranking URLs and one line each on why they rank. This does more for a writer than any word-count target.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Word count is a guide from the SERP, not a target. If the top results are 800 words, a 3,000-word essay is a worse answer, not a better one.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">List the entities: brands, places, tools, prices, people. Coverage of the real things in a topic is what separates useful content from paraphrased filler.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Always include a &#x27;do not claim&#x27; section. Health, legal, income and safety claims get clients in real trouble, and the VA is the one who wrote it.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Add two or three FAQ questions pulled from People Also Ask. Free structure, and it often wins the snippet.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Brief header for &#x27;how to store coffee beans philippines&#x27;</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">QUERY — how to store coffee beans philippines · 320/mo est. (Keyword Planner, 4 Aug 2026) · low difficulty</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">INTENT — Informational. Top 3 are all how-to guides with a section on humidity. Two have a comparison table.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">AUDIENCE — Home brewers in Metro Manila who just bought their first bag of beans and noticed they went stale fast.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">ANGLE — Humidity is the local problem nobody&#x27;s guides address. Lead with that, not with generic &#x27;keep away from sunlight&#x27;.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">COVER — airtight containers, one-way valve bags, freezing (and the condensation risk), humidity levels in MM, degassing, &#x27;roasted on&#x27; vs &#x27;best before&#x27; dates.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">LENGTH — 900–1,100 words. Top result is 1,040.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">INTERNAL LINKS — /shop/single-origin (anchor: freshly roasted single-origin beans), /blog/grind-size</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">DO NOT CLAIM — any health benefit, any specific shelf life in days without a source, that freezing is always safe.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">FAQ — Can you freeze coffee beans? How long do roasted beans last? Should beans be stored in the fridge?</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">A writer can start immediately from this, and you can review against it objectively instead of arguing about taste.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Brief to published post</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Every article. The brief is where you control quality; editing is where you lose your evenings.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Read the top 3 ranking pages properly</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Not skim. Note what they all cover (you must cover it), and what none of them cover (that&#x27;s your angle).</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Write the brief before you commission</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Target keyword, word count, the H2s, the angle, who the reader is, and 3 sources to cite. 20 minutes here saves 2 hours of rewriting.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Give the writer the one thing they can&#x27;t guess</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The client&#x27;s actual expertise. A quote from the founder, a real customer story, a number only this business knows. This is the only real differentiator left.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Edit for accuracy first, style second</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Check every claim and number. One wrong price on a client&#x27;s blog costs you more trust than ten clunky sentences.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Optimise on the way in, not after</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Title, meta, slug, internal links, alt text, schema — do it as you publish. &#x27;We&#x27;ll optimise it later&#x27; means never.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Add the internal link from an old page</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">A new post with no inbound internal links is an orphan. Find two existing pages and link to it the same day.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Publishing and moving on. Put a 90-day reminder on every post to check its Search Console data and update it. Refreshing old posts beats writing new ones for most small sites.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Content brief</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">One page. Hand this to any writer, including yourself. If a writer asks a question this doesn&#x27;t answer, add the answer to your template permanently.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>BRIEF: [working title]\nDue: [date] | Word count: [1,200–1,500] | Writer: [name] | Fee: [amount]\n\nTARGET\nPrimary keyword: [keyword] (vol [n], KD [n])\nSecondary: [3–5 variants to work in naturally]\nSearch intent: [informational / commercial / transactional]\nWhat the reader is actually trying to do: [one sentence]\n\nWHO&#x27;S READING\n[2 sentences. Their job, their problem, what they already know. &quot;Small cafe owners in Metro Manila who currently buy from a supermarket and suspect they&#x27;re overpaying.&quot;]\n\nTHE ANGLE\nTop 3 results all say: [the table stakes — we must cover this too]\nNone of them say: [our angle — lead with this]\nOur unfair advantage: [the client&#x27;s real expertise/data/story]\n\nSTRUCTURE\nH1: [title]\nIntro (100 words): answer the question immediately, then say what the piece covers\nH2: [heading]\n  - [point to make]\nH2: [heading]\n  - [point to make]\nH2: FAQ — [3 questions from AlsoAsked, answered in 40–60 words each]\nClose: [what the reader should do next + link to the money page]\n\nMUST INCLUDE\n• Internal links to: [url], [url]\n• Cite: [source], [source]\n• Quote from [client contact] — I&#x27;ll get this, don&#x27;t invent one\n• [Any specific number, price, or product name]\n\nDON&#x27;T\n• No &quot;in today&#x27;s fast-paced world&quot; openers\n• No stats without a source and a date\n• Don&#x27;t recommend competitors by name\n• Don&#x27;t claim anything about health, money or legal outcomes we can&#x27;t back up\n\nTONE\n[3 words] — e.g. &quot;plain, warm, a bit opinionated&quot;. Reference: [link to a page they should sound like]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Writer feedback that doesn&#x27;t take longer than rewriting</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">First draft came back wrong. Send this instead of silently fixing it, or you&#x27;ll be doing it forever.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Thanks [name] — solid structure, two things to fix before I can publish.\n\n1. [The biggest problem, named plainly.]\n   Example: the intro spends 3 paragraphs on background before answering the question. Cut to the answer in the first 2 sentences.\n   \n2. [Second problem.]\n   Example: the &quot;how to store beans&quot; section is generic — it could be on any site. The brief asked for [client]&#x27;s actual method. I&#x27;ve pasted their quote below, build the section around it.\n\nSmall stuff I&#x27;ll fix myself, no need to action: [typos, heading levels, links].\n\nCan you turn this around by [date]? Happy to jump on a 10-min call if the angle isn&#x27;t landing.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Write a full brief for one of the P2 rows in your keyword map from module 2.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page brief using all nine headings above.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 45 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You actually opened and summarised the top three results</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The angle is something the current top results are missing</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least eight specific entities are listed</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is a do-not-claim section</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Length is justified by the SERP, not picked out of the air</span></label></li></ul></div>"},{"n":5,"title":"Technical SEO you can safely do as a VA","outcome":"You can run a crawl, turn it into a prioritised issue log, and know exactly which fixes need someone senior to approve.","badges":["Workflow","Tools","1 template"],"minutes":42,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Run Screaming Frog on the free 500-URL tier. Your first pass looks for four things: broken links, redirect chains, duplicate titles, and pages missing from the sitemap.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Status codes in plain terms. 200 is fine, 301 is a permanent move and passes value, 302 is temporary and often used by mistake, 404 is gone, 5xx is the server failing and is urgent.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">A redirect chain is A → B → C. Fix it by pointing A straight at C. Chains waste crawl budget and lose a little value at each hop.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Canonicals tell Google which version of near-identical pages is the real one. Getting this wrong can deindex a whole section, so a junior finds and documents canonical problems, a senior changes them.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Orphan pages have no internal links pointing at them. Google may never find them. This is usually the cheapest win on a small site.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Core Web Vitals: LCP is how fast the main content appears, INP is how fast the page responds to a tap, CLS is how much things jump around. Report the field data from PageSpeed Insights, not the lab score.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Know your line. Find, evidence and recommend robots.txt, noindex and canonical changes. Never make them silently on a live site.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — An issue log row done properly</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">&#x27;There are a lot of 404s and some redirect issues on the site.&#x27;</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">ISSUE — 14 internal links point to /shop/kenya-aa which returns 404</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">EVIDENCE — Screaming Frog crawl 4 Aug 2026, Response Codes &gt; Client Error, tab &#x27;Inlinks&#x27; attached</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">IMPACT — Users hit dead ends from the main nav; crawl budget wasted; the page had 12% of organic entries in Jul</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">FIX — 301 /shop/kenya-aa → /shop/single-origin, then update the 14 internal links to point directly at the new URL</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">OWNER — Dev (redirect), me (internal link updates in WP)</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">RISK IF WRONG — Low. Redirect is reversible.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">PRIORITY — P1</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">Evidence, impact, owner, risk, priority. Do this and you stop being a VA who exports crawls and start being the person the agency lets talk to clients.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Crawl to prioritised issue log</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Month one of any new client, then quarterly.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Crawl with Screaming Frog, and let it finish</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Free tier does 500 URLs, which covers most small business sites. Export everything before you start filtering.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Cross-check against Search Console coverage</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The crawl shows what exists; Search Console shows what Google actually did with it. The gap between them is where the problems live.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Sort every issue into three buckets</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Blocking indexation / hurting rankings / cosmetic. Most &#x27;SEO audit&#x27; reports are 90% cosmetic and that&#x27;s why clients ignore them.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Mark who can fix each one</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Me (CMS access) / dev needed / decision needed from client. Be honest — attempting a dev fix and breaking the site is career-limiting.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Estimate impact and effort, then sort</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">High impact + low effort first, always. A client who sees one thing fixed in week one trusts you for the other twenty.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">6</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Fix the safe ones, log the rest with a ticket each</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Never hand over a PDF of problems with no owner. That&#x27;s a complaint, not a deliverable.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Touching robots.txt, canonicals or redirects on a live site without a backup and written sign-off. One bad line in robots.txt can deindex an entire business. Always screenshot the before state.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Tool comparison</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Technical SEO tools, and which ones you&#x27;re allowed to break things with</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The rule: read-only tools you can use freely from day one. Write-access tools need explicit permission and a backup.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:52rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tool</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Best for</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Learning curve</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cost</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Verdict</th></tr></thead><tbody><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Google Search Console</span><span class=\"mt-1 flex w-fit items-center gap-1 rounded-full bg-teal-wash px-2 py-[0.15rem] text-[0.625rem] font-bold uppercase tracking-[0.08em] text-teal-deep\"><svg aria-hidden=\"true\" viewBox=\"0 0 12 12\" class=\"h-2 w-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6.3 4.7 9 10 3.2\"></path></svg>Learn first</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Indexing status, coverage errors, Core Web Vitals, real query data.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy to open, months to read well</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Start every technical investigation here. The URL Inspection tool answers &#x27;why isn&#x27;t this page ranking&#x27; faster than anything else.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Screaming Frog</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Finding broken links, redirect chains, missing tags, thin pages at scale.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Medium — 2 evenings</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free to 500 URLs, £199/yr</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Read-only, so it&#x27;s safe. Learn it on your own site. Knowing this genuinely separates you from other applicants.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">PageSpeed Insights</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Core Web Vitals and a prioritised list of what&#x27;s slow.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy to run, hard to action</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Run it, but don&#x27;t promise speed fixes. Most require a developer. Report the score, name the top 2 causes, hand it over.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Rich Results Test</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Checking your schema markup actually validates.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Always test schema before you call it done. Invalid schema does nothing at best and gets a manual action at worst.</td></tr><tr class=\"border-b border-line align-top last:border-0\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Ahrefs Site Audit / Semrush Site Audit</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Scheduled crawls with a trend line the client can see.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Easy</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Bundled with the subscription</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Nice-to-have. The score is arbitrary — never report the number on its own, report which issues you closed.</td></tr><tr class=\"border-b border-line align-top last:border-0 bg-card/70\"><th scope=\"row\" class=\"py-2.5 pl-0 pr-3\"><span class=\"text-[0.875rem] font-semibold text-ink\">Wayback Machine</span></th><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-ink-2\">Seeing what a page looked like before traffic dropped.</td><td class=\"px-3 py-2.5 text-[0.8125rem] leading-snug text-muted\">Instant</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.8125rem] tabular-nums text-ink-2\">Free</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Underused detective tool. When a client says &#x27;it used to rank&#x27;, this is how you find out what changed.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 5 columns and scrolls horizontally on small screens.</span></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Technical issue log</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Replaces the 40-page audit PDF. One sheet, sorted by impact, with an owner on every line.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><div class=\"p-3.5 space-y-3\"><div class=\"overflow-x-auto rounded-lg border border-line\"><table class=\"w-full min-w-[600px] text-[0.8125rem]\"><thead><tr class=\"bg-paper-2\"><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">#</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Issue</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Pages affected</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Bucket</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Impact</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Effort</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Owner</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Status</th><th class=\"border-b border-line px-3 py-2.5 text-left font-semibold text-ink whitespace-nowrap\">Evidence</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">340 pages &quot;crawled – currently not indexed&quot;</td><td class=\"px-3 py-2.5 text-ink-2\">340</td><td class=\"px-3 py-2.5 text-ink-2\">Blocking</td><td class=\"px-3 py-2.5 text-ink-2\">High</td><td class=\"px-3 py-2.5 text-ink-2\">M</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">In progress</td><td class=\"px-3 py-2.5 text-ink-2\">GSC coverage, screenshot [link]</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">2</td><td class=\"px-3 py-2.5 text-ink-2\">Homepage H1 is an image, no text</td><td class=\"px-3 py-2.5 text-ink-2\">1</td><td class=\"px-3 py-2.5 text-ink-2\">Ranking</td><td class=\"px-3 py-2.5 text-ink-2\">High</td><td class=\"px-3 py-2.5 text-ink-2\">S</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">Done</td><td class=\"px-3 py-2.5 text-ink-2\">Frog export row 1</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">3</td><td class=\"px-3 py-2.5 text-ink-2\">Redirect chain /shop → /store → /products</td><td class=\"px-3 py-2.5 text-ink-2\">60</td><td class=\"px-3 py-2.5 text-ink-2\">Ranking</td><td class=\"px-3 py-2.5 text-ink-2\">Med</td><td class=\"px-3 py-2.5 text-ink-2\">S</td><td class=\"px-3 py-2.5 text-ink-2\">Dev</td><td class=\"px-3 py-2.5 text-ink-2\">Ticketed</td><td class=\"px-3 py-2.5 text-ink-2\">Frog redirect report</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">4</td><td class=\"px-3 py-2.5 text-ink-2\">No LocalBusiness schema anywhere</td><td class=\"px-3 py-2.5 text-ink-2\">site</td><td class=\"px-3 py-2.5 text-ink-2\">Ranking</td><td class=\"px-3 py-2.5 text-ink-2\">Med</td><td class=\"px-3 py-2.5 text-ink-2\">S</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">To do</td><td class=\"px-3 py-2.5 text-ink-2\">Rich Results Test</td></tr><tr class=\"border-b border-line last:border-0 hover:bg-paper-2/50 transition-colors\"><td class=\"px-3 py-2.5 text-ink-2\">5</td><td class=\"px-3 py-2.5 text-ink-2\">12 broken outbound links in old posts</td><td class=\"px-3 py-2.5 text-ink-2\">12</td><td class=\"px-3 py-2.5 text-ink-2\">Cosmetic</td><td class=\"px-3 py-2.5 text-ink-2\">Low</td><td class=\"px-3 py-2.5 text-ink-2\">S</td><td class=\"px-3 py-2.5 text-ink-2\">Me</td><td class=\"px-3 py-2.5 text-ink-2\">To do</td><td class=\"px-3 py-2.5 text-ink-2\">Frog 404 report</td></tr></tbody></table></div><pre class=\"font-mono text-[0.78125rem] leading-relaxed text-ink-2 whitespace-pre-wrap\">RULES\n• Bucket: Blocking (Google can&#x27;t see it) &gt; Ranking (Google sees it, doesn&#x27;t like it) &gt; Cosmetic\n• Effort: S = under 1hr, M = under a day, L = needs a dev sprint\n• Never more than 3 &quot;High&quot; items open at once — fix them, then promote the next three\n• Every row needs Evidence. &quot;Trust me&quot; is not an audit.\n\n⚠ NEEDS WRITTEN SIGN-OFF BEFORE I TOUCH IT\n• robots.txt changes\n• Canonical tag changes\n• Any redirect on a page that currently gets traffic\n• Anything that deletes a URL</pre></div></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Crawl any small public site with Screaming Frog free. Produce an issue log of the top eight problems using the seven fields above.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: An eight-row prioritised issue log with the crawl export attached.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 80 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every row cites specific evidence with a date, not a general impression</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Priorities are P1/P2/P3 with a stated reason</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You marked which fixes need senior or client approval</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No row says &#x27;fix SEO&#x27; or anything else unactionable</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You noted at least one thing that looks broken but is actually fine</span></label></li></ul></div>"},{"n":6,"title":"Off-page and local, without buying spam","outcome":"You can prospect real links and set up local presence properly, and turn down the schemes that get clients penalised.","badges":["Red/green flags","2 templates"],"minutes":30,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One relevant link from a site whose audience overlaps with the client beats a hundred directory links. Relevance and traffic, not just a DR number.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Link gap analysis is the most useful prospecting method: find sites linking to two competitors but not to your client. Those sites already cover the topic.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Personalise outreach or do not send it. Name the specific page, say what you would add, and keep it under 120 words.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Local SEO is mostly consistency. Name, address and phone identical everywhere, correct categories in the Google Business Profile, real photos, and replies to reviews.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Citation cleanup is boring, unglamorous, billable work that genuinely moves the map pack for small businesses. Good beginner offer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Refuse paid link schemes, PBNs, link exchanges at scale, and fake reviews. Fake reviews are also illegal in several markets, not just against policy.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">When a client says &#x27;our competitor does it&#x27;, the honest answer is: they might be getting away with it now, and you will still be the one holding the site when it stops working.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — Outreach email that occasionally works</p><div class=\"mb-3 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Before</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Subject: Link exchange opportunity</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Hi, I came across your website and I think we could benefit from a mutual link exchange. Let me know if interested. We have high DA sites available.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">After</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Subject: your Benguet coffee guide — missing the roast date thing</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Hi Marla — your guide to Philippine coffee regions is the one I keep sending people. One gap: you mention buying local but not how to read a roast date, which is the thing that actually ruins most people&#x27;s first bag.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">We published a short piece on it last week with humidity data for Metro Manila. If it&#x27;s useful as a link under your &#x27;buying tips&#x27; section, here it is: [url]. If not, no worries, genuinely.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">— Liza, Baler Coffee Roasters</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The second one gets a reply maybe one time in fifteen, which is a good rate. The first one gets you filtered forever.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A vendor emails offering links</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;DA 60+ guest post placements, permanent do-follow, $45 each. Bulk discount available. 500 sites in our network, instant approval, casino/CBD niches accepted.&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">A private blog network. &quot;Instant approval&quot;, &quot;our network&quot; and a niche list that includes casino are the tells. These links work briefly and then take the client&#x27;s site down with them. You will be blamed.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Hi — I run [client], a coffee roaster in Manila. I read your piece on [specific article] and noticed you link to a bean storage guide that&#x27;s 404ing now. We published one last month that covers the same ground plus humidity, which matters here. Happy for you to use it or not — either way, the broken link is at paragraph 6.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">You gave them something useful before asking, referenced a real page, and made it easy to say no. Hit rate is maybe 5%, but the links are real and permanent.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">Setting up a Google Business Profile</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Stuffing the business name field: &quot;Manila Coffee Beans - Best Coffee Roaster Delivery Philippines&quot;</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Direct violation of Google&#x27;s guidelines and the single easiest thing for a competitor to report. Suspension takes minutes; reinstatement takes weeks and sometimes never happens.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Name exactly as it appears on the shopfront and receipts: &quot;Baler Coffee Co.&quot; Then win by filling in everything else: every service, real hours including holidays, 20+ genuine photos, products with prices, weekly posts, and replying to every review within 48 hours.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">The name field is a trap. The completeness of everything else is what actually ranks you in the map pack, and it&#x27;s entirely within your control.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Broken link outreach</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">The highest hit-rate outreach there is, because you&#x27;re doing them a favour first. Send 20, expect 1–2.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Subject: broken link on [page title]\n\nHi [first name],\n\nSmall thing — the link to [old resource] in your [article name] piece is dead. It&#x27;s in the [section/paragraph] section, points to [dead url].\n\nI only noticed because I was researching the same topic. We published [our resource] recently which covers [what it covers] — you&#x27;re welcome to use it as the replacement, or not, no pressure either way. The broken link&#x27;s worth fixing regardless.\n\n[Your name]\n[Client business], [city]</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Local SEO setup checklist</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Any client with a physical location or a service area. Do all of it in week one — it&#x27;s the fastest measurable win in SEO.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>GOOGLE BUSINESS PROFILE\n[ ] Claimed and verified\n[ ] Name matches signage EXACTLY — no keywords, no city, no tagline\n[ ] Primary category is the most specific one that fits (this matters more than anything else)\n[ ] 2–4 secondary categories\n[ ] Full address, or service area set if there&#x27;s no walk-in\n[ ] Hours, plus special hours for every PH holiday\n[ ] Phone number that a human answers\n[ ] Website link with UTM tracking so you can prove the traffic\n[ ] Description: 750 chars, natural, mentions the city once\n[ ] 20+ photos: exterior, interior, team, products, at different times of day\n[ ] Products/services listed with real prices\n[ ] Q&amp;A section seeded with 5 real questions the business gets asked\n[ ] Weekly Post (offer, update, event)\n\nNAP CONSISTENCY — name, address, phone identical everywhere\n[ ] Website footer and contact page\n[ ] Facebook page\n[ ] Any directory they&#x27;re already on\n[ ] Apple Maps / Waze\nSearch the phone number in quotes to find listings you didn&#x27;t know existed.\n\nON-SITE\n[ ] LocalBusiness schema with address, hours, geo coordinates\n[ ] A real page per location or service area — not a doorway page, actual content\n[ ] Embedded map on the contact page\n[ ] City mentioned naturally in title, H1 and body of the main service page\n\nREVIEWS\n[ ] A short link saved for requesting reviews\n[ ] A process: who asks, when, how (in person beats email)\n[ ] Reply to every review within 48 hrs, including the bad ones, especially the bad ones\n[ ] Never buy reviews. It is trivially detectable and it is unrecoverable.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Pick two competitors in your chosen niche. Find five sites that link to both of them but not to your client. Write one outreach email to the best target.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A five-row prospect sheet with a relevance note per row, plus one outreach email under 120 words.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Each prospect has a named contact or a real contact route</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You wrote why their audience overlaps, in one sentence per row</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The email names a specific page and a specific gap</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Nothing in the email offers money or a reciprocal link</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You rejected at least one prospect and said why</span></label></li></ul></div>"},{"n":7,"title":"Reporting that survives a sceptical client","outcome":"You can pull the data, compare it honestly, and write three recommendations instead of forty charts.","badges":["Red/green flags","2 templates"],"minutes":32,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Compare like with like. Month over month is contaminated by seasonality and different day counts. Year over year and 28-day-versus-previous-28 are safer.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Separate traffic from outcomes. Impressions up with clicks flat means you are ranking for the wrong things, and saying that out loud builds more trust than a green arrow.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Always explain anomalies before the client asks. A holiday, an algorithm update, a site outage, a tracking change. Unexplained spikes make clients suspicious of everything else.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">The report opens with a three-line summary: what happened, why, what we do next. The charts go underneath for the people who want them.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Never report rank alone. Position 4 on a term nobody searches is worth less than position 11 on a term that converts.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Build it once in Looker Studio, connect GSC and GA4, and it refreshes itself. That is a real hour-saving that lets you take more clients.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The top of a monthly report</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">WHAT HAPPENED — Organic clicks 1,840, up 22% vs the same 28 days last year. Non-brand clicks up 31%. Conversions from organic 44, flat.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">WHY — The three P1 pages published in June are now ranking 8–14 for their primary terms. Conversion is flat because /wholesale still has no enquiry form above the fold.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">CAUTION — Impressions spiked 9–11 July from a single term, &#x27;coffee&#x27;, which sent almost no clicks. Excluded from the trend line so it does not flatter the numbers.</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">NEXT — 1) Add an enquiry form to /wholesale. 2) Internal links from the two strongest blog posts into /shop/single-origin. 3) Fix the 14 broken links from the crawl.</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">The caution line is the one that earns the renewal. Clients have all been burned by an agency reporting a fake spike as a win.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Red flag / green flag</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Spot the difference</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Same situation, two ways it can go.</p><div class=\"mt-4\"><div class=\"space-y-4\"><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">The monthly report you send</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">A 34-slide deck of every chart the tool exports. Impressions, clicks, CTR, position, bounce rate, sessions by device, top 100 keywords, backlink count, domain authority score — all with no commentary.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">Nobody reads it. The client concludes you&#x27;re padding to look busy, and when they cancel they&#x27;ll say &quot;we never really understood what you were doing&quot;. Volume of charts is inversely correlated with retention.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">A one-page email: the three numbers that matter, what changed and why, what you&#x27;re doing next month, and one thing you need from them. Full data in a linked appendix for anyone who wants it.</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Founders skim on their phone. Write for that. The appendix means you&#x27;re not hiding anything — you&#x27;re just respecting their time.</p></div></div></div><div><p class=\"mb-2 text-[0.8125rem] font-semibold text-ink\">A month where the numbers went down</p><div class=\"grid gap-2.5 sm:grid-cols-2\"><div class=\"rounded-lg border border-[#e8b9a8] bg-clay-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-clay-deep\">Red flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">Leading with the good metric you can find, burying the drop on slide 19, or quietly not sending the report at all.</p><p class=\"mt-2 border-t border-[#f0d5cd] pt-2 text-[0.75rem] leading-relaxed text-clay-deep\">They have Analytics too. Getting caught spinning a bad month costs the relationship permanently, and bad months are normal in SEO.</p></div><div class=\"rounded-lg border border-teal-pale bg-teal-wash/70 p-3.5\"><p class=\"eyebrow mb-1.5 text-teal-deep\">Green flag</p><p class=\"whitespace-pre-line text-[0.8125rem] italic leading-relaxed text-ink-2\">&quot;Clicks down 14% this month. Two reasons: [competitor] published a better version of our top page, and the seasonal dip we saw last February repeated. Neither is a surprise and here&#x27;s the plan: I&#x27;m rewriting that page this week with the pricing table they don&#x27;t have, and I&#x27;ve queued two posts for the terms that hold up year-round.&quot;</p><p class=\"mt-2 border-t border-teal-pale pt-2 text-[0.75rem] leading-relaxed text-teal-deep\">Named the drop first, gave real causes, distinguished the controllable from the seasonal, and moved straight to action. Clients forgive bad months. They don&#x27;t forgive being managed.</p></div></div></div></div></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal these</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Monthly SEO report</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Paste into the email body. Not an attachment — attachments don&#x27;t get opened.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>[Client] SEO — [Month]\n\nTHE THREE NUMBERS\nClicks: [n] ([+/-n%] vs last month, [+/-n%] vs same month last year)\nImpressions: [n] ([+/-n%])\nConversions/enquiries from organic: [n] ([+/-n%])\n\nWHAT CHANGED AND WHY\n[2–4 sentences. Cause, not just effect. If something dropped, say so first.]\n\nBIGGEST WIN\n[One specific thing. &quot;The bean storage guide went from position 14 to 4 and now brings 180 clicks/month — that&#x27;s more than the homepage.&quot;]\n\nWHAT I DID\n• [Thing] — [result or status]\n• [Thing] — [result or status]\n• [Thing] — [result or status]\n\nNEXT MONTH\n1. [Specific action, with the reason]\n2. [Specific action, with the reason]\n3. [Specific action, with the reason]\n\nWHAT I NEED FROM YOU\n[One thing. A quote, a decision, dev time, a photo. Only ever ask for one.]\n\nFull data: [link to the appendix sheet]\n\nYEAR-ON-YEAR NOTE\nSEO compounds and it&#x27;s seasonal. Month-to-month is noise; the line that matters is [current month] vs [same month last year], which is [+/-n%].</code></pre></div><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">The &#x27;is it working?&#x27; answer</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Month 3 or 4, when the client gets nervous. Have this ready before they ask.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Fair question, and here&#x27;s my honest read.\n\nLeading indicators (these move first, in months 1–4):\n• Indexed pages: [n] → [n]\n• Impressions: [n] → [n] — Google is showing us more often\n• Keywords ranking in the top 20: [n] → [n]\n• Average position for our target set: [n] → [n]\n\nLagging indicators (these move in months 4–9):\n• Clicks: [n] → [n]\n• Enquiries from organic: [n] → [n]\n\nWhere we are: [honest sentence. &quot;Impressions are up 60% but clicks are flat, which means we&#x27;re appearing and not being clicked — that&#x27;s a titles and meta problem, and it&#x27;s a fixable one.&quot;]\n\nWhat would make me tell you to stop: [name it. &quot;If impressions were flat too, I&#x27;d say the strategy is wrong and we should talk.&quot;]\n\nRealistic timeline from here: [specific]. If [metric] hasn&#x27;t moved by [month], we should reassess together.</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Use any GSC property you can access, including a personal site or one you set up for practice, and write a full monthly report from its real data.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page report with the four headings above and a simple Looker Studio dashboard link.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 70 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The comparison period is stated and defensible</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Non-brand traffic is separated from brand traffic</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">At least one anomaly is explained without being asked</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There are exactly three recommendations, each with a named owner</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">No metric appears without context or a comparison</span></label></li></ul></div>"},{"n":8,"title":"Capstone: the Baler Coffee audit","outcome":"You have a full client-ready SEO deliverable pack built on real data from a real site you have permission to touch.","badges":["Workflow","Rates","1 template"],"minutes":120,"html":"<ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do this on a real site: your own, a friend&#x27;s, a barangay group, a small non-profit. Real GSC data beats invented numbers every time and you will learn ten things you cannot learn from a mock.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Attribution is not optional. Label everything as personal project, simulated, or permissioned client work. Presenting someone else&#x27;s results as yours is the fastest way to get blacklisted in a small industry.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Include the QA checklist and change log in the pack. It shows you work in a way an agency can insure.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do not promise an outcome in the pack. Promise a process, then show the evidence of the process working.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">One Reddit beginner did exactly this, took a sandbox site&#x27;s PageSpeed from 40 to 90, cleaned the on-page and technical issues, then emailed 20 local businesses and got zero replies. The site was not the problem. Cold email at volume is. Warm routes work better: agencies who need implementation help, friends of friends, and non-profits with a defined project.</span></li></ul><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — The eight files in the pack</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">1. Audit summary, one page, three priorities</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">2. Keyword map, 20+ rows with intent and priority</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">3. Content brief for the top-priority page</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">4. On-page before/after for one page with character counts</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">5. Technical issue log with the crawl export</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">6. Local citation audit, if the client is local</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">7. One outreach email plus a five-row prospect sheet</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">8. Monthly report and a Looker Studio dashboard link</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Plus: a QA checklist and a dated change log covering everything you touched</p></div><p class=\"mt-3 text-[0.875rem] italic leading-relaxed text-ink-2\">This pack is more evidence than most junior SEO applicants have after a year of employment. It is also the thing that lets you skip the ₱15,000 bootcamp.</p></div><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Workflow</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Turning the audit into a portfolio piece and a pitch</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The day you finish the Baler Coffee capstone.</p><div class=\"mt-4\"><ol class=\"relative space-y-0\"><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">1</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Anonymise if you need to, but keep the numbers</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;A 40-page coffee retailer&quot; is fine. &quot;Improved SEO&quot; is not. Numbers are the entire value of a case study.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">2</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Lead with the diagnosis, not the deliverables</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">&quot;340 pages were invisible to Google because of one line in robots.txt&quot; is a story. &quot;I did a technical audit&quot; is a task.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">3</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Show one real artefact in full</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">The issue log or the keyword map. Clients want to see the actual quality of your thinking, not a summary of it.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"absolute left-[0.84rem] top-7 bottom-0 w-px bg-line-2\"></span><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">4</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Include what you&#x27;d do next and what it&#x27;d cost</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">End the case study with the pitch. A portfolio that doesn&#x27;t ask for the work is a diary.</p></div></li><li class=\"relative flex gap-3.5 pb-4 last:pb-0\"><span aria-hidden=\"true\" class=\"relative z-10 mt-0.5 grid h-[1.7rem] w-[1.7rem] shrink-0 place-items-center rounded-full border border-teal-pale bg-teal-wash font-display text-[0.75rem] font-extrabold tabular-nums text-teal-deep\">5</span><div class=\"min-w-0 flex-1 pt-[0.2rem]\"><p class=\"text-[0.9375rem] font-semibold leading-snug text-ink\">Record a 3-minute Loom walking through Search Console</p><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Screen-share your reasoning. This is what convinces a client you can actually do it rather than having read about it.</p></div></li></ol><p class=\"mt-4 rounded-lg border border-[#f0d5cd] bg-clay-wash/60 px-3.5 py-2.5 text-[0.8125rem] leading-relaxed text-ink-2\"><span class=\"font-bold text-clay-deep\">Where this breaks: </span>Presenting practice work as a paid client engagement. Say it&#x27;s a practice audit. Clients respect it, and getting caught inventing clients ends the conversation permanently.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">What this pays</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">What the capstone pack is worth as a paid engagement</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Once you&#x27;ve built this once for practice, you can sell the same thing. These are realistic first-client prices, not agency prices.</p><div class=\"mt-4\"><div><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:38rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Experience</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Hourly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Monthly (USD)</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What changes it</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Technical audit + issue log</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">6–10 hrs</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$150–400 one-off</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">The easiest thing to sell cold. Low risk for them, fast for you.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Keyword map + 3-month content plan</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">8–12 hrs</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$250–600 one-off</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Often turns into the retainer, because they need someone to execute it.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Local SEO setup (GBP + citations + schema)</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">5–8 hrs</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$200–450 one-off</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Fastest visible result in all of SEO. Great first project.</td></tr><tr class=\"border-b border-line last:border-0 bg-card/70\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ongoing retainer — 10 hrs/wk</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$8–14 effective</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$400–900/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">4 posts + on-page + reporting. Ask for a 3-month minimum; SEO can&#x27;t prove itself in one.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Ongoing retainer — 20 hrs/wk</th><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] font-semibold tabular-nums text-teal-deep\">$10–16 effective</td><td class=\"whitespace-nowrap px-3 py-2.5 text-[0.875rem] tabular-nums text-ink-2\">$900–1,800/mo</td><td class=\"py-2.5 pl-3 pr-0 text-[0.8125rem] leading-snug text-muted\">Adds technical, outreach and strategy. This is the target within 18 months.</td></tr></tbody></table></div></div><span class=\"sr-only\">This table has 4 columns and scrolls horizontally on small screens.</span></div><p class=\"mt-3 text-[0.75rem] leading-relaxed text-muted-2\">Sell the audit first. It&#x27;s a low-commitment yes, it proves you&#x27;re competent, and roughly half of them convert into a retainer.</p></div></section><section class=\"rounded-xl border border-line-2 bg-paper-2/60 p-4 sm:p-5\"><p class=\"eyebrow mb-1.5 text-muted\">Copy-paste</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Steal this</h4><p class=\"mt-1 text-[0.8125rem] leading-relaxed text-muted\">Swap the bracketed bits and send.</p><div class=\"mt-4\"><div class=\"space-y-3.5\"><div class=\"overflow-hidden rounded-lg border border-line bg-card\" data-template-block><div class=\"flex items-start gap-3 border-b border-line bg-paper-2/70 px-3.5 py-2.5\"><div class=\"min-w-0 flex-1\"><p class=\"text-[0.875rem] font-semibold leading-snug text-ink\">Cold audit pitch</p><p class=\"mt-0.5 text-[0.75rem] leading-snug text-muted\">Send to a small business whose site you&#x27;ve actually looked at for 10 minutes. Specificity is the whole thing.</p></div><button type=\"button\" data-copy-template class=\"inline-flex h-7 shrink-0 items-center gap-1.5 rounded-full border px-2.5 text-[0.6875rem] font-bold uppercase tracking-[0.08em] transition-colors border-line-input bg-card text-muted hover:border-ink hover:text-ink\">Copy<span class=\"sr-only\"> template to clipboard</span></button></div><pre class=\"overflow-x-auto px-3.5 py-3 font-mono text-[0.78125rem] leading-relaxed text-ink-2\"><code class=\"whitespace-pre-wrap break-words\" data-template-body>Subject: 3 things costing you search traffic at [business name]\n\nHi [name],\n\nI had a look at [site] this morning — I&#x27;m an SEO specialist and I do this to a few local businesses a week. Three things stood out:\n\n1. [Specific, verifiable problem.] e.g. &quot;Your homepage title is just &#x27;Home&#x27; — Google is showing that in search results instead of your business name.&quot;\n2. [Specific problem.] e.g. &quot;You rank #7 for &#x27;coffee beans manila&#x27; but the page it&#x27;s ranking is a blog post from 2021, not your shop page.&quot;\n3. [Specific problem.] e.g. &quot;Your Google Business Profile has no products listed, and the two competitors above you in the map both do.&quot;\n\nAll three are fixable in under a week. I&#x27;m not going to pretend that transforms your business, but they&#x27;re free traffic you&#x27;re currently leaving on the table.\n\nIf it&#x27;s useful, I&#x27;ll do a full audit — every issue, prioritised, with what to fix first — for [$X]. If you&#x27;d rather just take the three above and do them yourself, genuinely, go ahead. They&#x27;re yours.\n\n[Your name]\n[portfolio link]</code></pre></div></div></div></section><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Assemble the full pack for a real site you have permission to work on. Publish it as a case study page with an honest attribution note.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A shareable case study link with all eight artefacts and a change log.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 120 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every claim in the case study is backed by a screenshot with a date</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The attribution note says clearly whose site it is and what your role was</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The change log lists every edit with dates so results can be traced to causes</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">There is no guaranteed outcome anywhere in the document</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">A stranger can understand what you did in under four minutes</span></label></li></ul></div>"},{"n":9,"title":"The local SEO delivery system","outcome":"You can run a local client month by month in the order agencies actually train it, from Business Profile to the proposal.","badges":["Local SEO","Agency SOP","4 tables"],"minutes":45,"html":"<div class=\"space-y-6\"><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">Everything so far taught you the skills. This module gives you the order — the sequence a real agency uses to train new local SEO staff, starting with the visible, tangible wins and ending with the strategy work. Follow it and you will never sit in front of a new client wondering what to do first.</p><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The delivery order</h4><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:44rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Step</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What it is</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Why this order</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">1 · Business Profile</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Optimise the Google Business Profile: categories, services, photos, weekly posts, review replies, holiday hours.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">It dominates local search and every change is visible the same week — momentum for you and the client.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">2 · Citations</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Create or fix listings on directories (Yelp, BBB, Yellow Pages and the local ones).</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Golden rule: every listing matches the Business Profile exactly. Consistency is the whole job.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">3 · Rank tracking</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Set up local rank tracking and identify the three competitors that keep beating you.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">You cannot report progress you never measured. Baseline before you change anything.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">4 · Location pages</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">One page per service area: title and H1 with the place name, service info, map, reviews, FAQs, internal links.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">This is where local content lives. Thin duplicates get ignored; real pages rank.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">5 · Content</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Blogs, service pages and guides matched to intent, written naturally.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Now that the local plumbing works, content is what expands the reach.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">6 · Backlinks</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Foundational links first, content-based links second (table below).</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Links amplify pages that already deserve to rank. Doing this earlier wastes them.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">7 · Research</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Keyword research, competitor analysis and the backlink gap — what links to them but not to you.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">By now you understand the business well enough for research to produce a plan, not a list.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">8 · Technical</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Titles, metas, headers, broken links, page speed, mobile view, internal linking map, schema.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">The engineering pass. Local Business, FAQ and Review schema are the ones that matter here.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">9 · Off-page</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">NAP consistency across social profiles; press releases for credibility.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Reinforcement, not foundation. Cheap to do once everything else is right.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">10 · The proposal</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Present rankings and competitor data, propose strategy, pricing and deliverables.</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Last on purpose: you can only sell strategy you have actually executed.</td></tr></tbody></table></div></div></div><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Backlinks: the two tiers, and the anchor rule</h4><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">Local clients get burned by link sellers constantly. Here is the honest version of what links are worth buying with time (never with spam).</p><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:40rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Tier</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Typical DR</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Examples</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Effort</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What it does</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Foundational</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">DR 10–30</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Directories, listings, local associations</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Easy — hours</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Low SEO power, high necessity. The base layer every local business needs.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Content-based</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">DR 40+</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Guest posts, articles, resource mentions</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Hard — weeks of outreach</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">The links that actually move competitive rankings.</td></tr></tbody></table></div></div></div><ul class=\"space-y-3\"><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Anchor text needs diversity: mostly branded (&#x27;Baler Coffee&#x27;), some generic (&#x27;this guide&#x27;, &#x27;their website&#x27;), only a little exact-keyword. All-keyword anchors look bought, because they usually are.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">Do-follow links pass ranking value; no-follow links pass little. Check before celebrating — but a no-follow from a real local site still sends customers.</span></li><li class=\"flex gap-3\"><span aria-hidden=\"true\" class=\"mt-[0.5rem] h-1.5 w-1.5 shrink-0 rounded-full bg-teal-soft\"></span><span class=\"text-[0.9375rem] leading-relaxed text-ink-2\">If a link seller quotes you &#x27;DR 60 for $30&#x27;, the DR is inflated, the site is a link farm, or both. Walk away.</span></li></ul><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">Keyword mapping by page type</h4><p class=\"text-[1.0625rem] leading-[1.75] text-ink-2\">Intent decides the page. Learning intent needs a blog, buying intent needs a service page, comparing intent needs a guide. Then each page type gets its own keyword pattern — here mapped to Baler Coffee:</p><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:42rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Page type</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Keyword pattern</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Baler Coffee example</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Homepage</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Main term + city</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">&#x27;specialty coffee roaster quezon city&#x27;</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Service / category page</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Service term + city</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">&#x27;coffee bean subscription quezon city&#x27;</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Blog post</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Informational SERP term</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">&#x27;how to store coffee beans philippines&#x27;</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Location page</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Service near neighbourhood</td><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">&#x27;coffee shop near katipunan&#x27;</td></tr></tbody></table></div></div></div><h4 class=\"font-display text-[1.0625rem] font-semibold leading-snug text-ink\">The reporting cadence clients keep paying for</h4><div class=\"mt-4\"><p class=\"mb-1.5 text-[0.6875rem] font-semibold uppercase tracking-[0.08em] text-muted-2 sm:hidden\">Swipe the table sideways →</p><div class=\"-mx-4 overflow-x-auto px-4 sm:mx-0 sm:px-0\"><div style=\"min-width:36rem\"><table class=\"w-full border-collapse text-left\"><thead><tr class=\"border-b border-line-2\"><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">Cycle</th><th scope=\"col\" class=\"px-3 py-2 text-[0.6875rem] font-bold uppercase tracking-[0.1em] text-muted first:pl-0 last:pr-0\">What you deliver</th></tr></thead><tbody><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Weekly</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Business Profile updates and posts, ranking check, review replies.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Monthly</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Backlinks won, content published, movement on tracked keywords, three recommendations.</td></tr><tr class=\"border-b border-line last:border-0\"><th scope=\"row\" class=\"whitespace-nowrap py-2.5 pl-0 pr-3 text-[0.875rem] font-semibold text-ink\">Quarterly</th><td class=\"px-3 py-2.5 text-[0.875rem] leading-snug text-ink-2 \">Citation audit, technical audit, organic keyword audit — what is working, what to stop.</td></tr></tbody></table></div></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-line-2 bg-paper-2\"><p class=\"eyebrow mb-2.5 text-muted\">Worked example — first month on a new local client</p><div class=\"rounded-lg border border-line-2 bg-card p-3.5\"><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Week 1 → Business Profile audit + fixes, baseline rank tracking, competitor list</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Week 2 → Citation sweep: fix 12 listings to match the Profile exactly</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Week 3 → First location page drafted + review request flow switched on</p><p class=\"font-mono text-[0.8125rem] leading-relaxed text-ink-2\">Week 4 → First monthly report: what changed, what moved, what&#x27;s next</p></div></div><div class=\"rounded-xl border p-4 sm:p-5 border-teal-pale bg-teal-wash/60\"><p class=\"eyebrow mb-2.5 text-muted\">Do this</p><p class=\"text-[0.9375rem] leading-relaxed text-ink\">Pick a real local business you know. Run steps 1–3 as a paper exercise: audit their Business Profile against the checklist above, find five citation inconsistencies, and list the three competitors that outrank them on one map search.</p><div class=\"mt-3.5 flex flex-wrap items-center gap-2\"><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-accent-soft text-accent-deep border-transparent\">Hand in: A one-page audit note with the Profile gaps, the five citation fixes, and the competitor list.</span><span class=\"inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[0.6875rem] font-semibold tracking-wide bg-paper-2 text-ink-2 border-transparent\">≈ 60 min</span></div><p class=\"eyebrow mt-4 mb-2 text-muted\">Check before you call it done</p><ul class=\"space-y-1.5\"><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">Every citation fix quotes the exact wrong text and the exact right text</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">The competitor list comes from an actual map search you screenshotted</span></label></li><li><label class=\"flex cursor-pointer gap-2.5 text-[0.875rem] leading-relaxed text-ink-2 hover:text-ink\"><span class=\"mt-0.5 shrink-0\"><span class=\"inline-flex h-4 w-4 rounded border border-line-3 bg-card\"></span></span><input type=\"checkbox\" class=\"sr-only\"/><span class=\"\">You wrote one sentence on which delivery step you would start with, and why</span></label></li></ul></div></div>"}],"quiz":[{"q":"A client wants a page removed from Google. What is the correct move?","options":["Block it in robots.txt","Add a noindex tag and let Google crawl the page","Delete it and let the 404 handle it","Add a canonical to the homepage"],"answer":1,"explain":"Noindex only works if Google can crawl the page to see the tag. Blocking it in robots.txt first actually prevents removal, which is the classic beginner trap."},{"q":"Impressions are up 40% but clicks are flat. What does that most likely mean?","options":["The site is being penalised","You are ranking for terms that do not match what searchers want, or ranking too low to be clicked","GA4 is broken","The content is too short"],"answer":1,"explain":"Impressions without clicks is a relevance or position problem. Report it honestly, check which queries drove it, and it usually points straight at your next fix."},{"q":"You find that /services and /our-services have near-identical content and both rank around position 20.","options":["Add more keywords to both","Delete one immediately","Document the duplication, recommend consolidating into one URL with a 301, and flag it for approval","Set both to noindex"],"answer":2,"explain":"That is cannibalisation and the fix is consolidation. But redirects and canonical changes are senior or client-approved calls. Your job is to find it, evidence it, and recommend."},{"q":"The client says their competitor buys links, so you should too.","options":["Buy them, the client accepted the risk","Explain the penalty risk in writing, offer a real link plan, and decline the paid links","Buy cheaper ones so it is less obvious","Agree and quietly do nothing"],"answer":1,"explain":"Put your position in writing so there is a record, offer the legitimate alternative, and decline. 'Agree and do nothing' seems safe but you own the outcome either way."},{"q":"You are picking a page target for the query 'espresso machine repair quezon city'.","options":["A 2,000-word blog post about espresso machine maintenance","A local service page, plus getting the Google Business Profile right","The homepage","A product category page"],"answer":1,"explain":"That SERP is a map pack and local service pages. Blog content will not win it no matter how good it is, because it is the wrong format for the intent."},{"q":"Which of these belongs in a technical issue log row?","options":["'Site speed is bad'","'LCP is 4.8s on mobile for /shop (PSI field data, 4 Aug), driven by an unoptimised 2.1MB hero image. Fix: compress and serve WebP. Owner: dev. P2.'","'Need to improve Core Web Vitals'","'Google says the site is slow'"],"answer":1,"explain":"Metric, measurement source, date, cause, fix, owner, priority. That structure is the difference between a VA who exports crawls and one who gets promoted."}],"glossary":[{"term":"SERP","def":"Search engine results page. The thing you should look at before forming any opinion."},{"term":"Search intent","def":"What the searcher is actually trying to do: learn, compare, buy, or find a specific site."},{"term":"Keyword cluster","def":"A group of related terms one page can serve together, instead of one page per phrase."},{"term":"Cannibalisation","def":"Two of your pages competing for the same term, so Google picks one, usually the wrong one."},{"term":"Backlink","def":"A link from another site to yours. Quality and relevance matter far more than count."},{"term":"Referring domain","def":"A unique site linking to you. Fifty links from one site is still one referring domain."},{"term":"DR / DA","def":"Domain Rating and Domain Authority. Third-party link-strength scores, not Google metrics."},{"term":"EMD","def":"Exact-match domain, like bestcoffeemanila.com. Once a shortcut, now mostly a liability."},{"term":"Canonical","def":"The tag saying which URL is the master version of near-duplicate pages."},{"term":"Noindex","def":"A tag telling search engines to keep a page out of the index. Needs to be crawlable to work."},{"term":"Robots.txt","def":"Crawler access instructions. Blocks crawling, does not reliably remove pages from the index."},{"term":"Crawl budget","def":"How much crawling attention a site gets. Only really matters on large sites."},{"term":"301 / 302","def":"Permanent and temporary redirects. Use 301 for real moves; 302s left in place cause problems."},{"term":"404","def":"Page not found. Fine for genuinely dead pages, bad when your own nav links to it."},{"term":"Orphan page","def":"A page with no internal links pointing at it, so nobody, human or crawler, finds it."},{"term":"CTR","def":"Click-through rate. Clicks divided by impressions. The metric your title and meta actually control."},{"term":"Impressions","def":"How many times your result was shown. High impressions with no clicks is a diagnosis, not a win."},{"term":"Core Web Vitals","def":"LCP (loading), INP (responsiveness), CLS (visual stability). Report field data, not lab scores."},{"term":"Schema markup","def":"Structured data that tells machines what a page contains. Can earn rich results."},{"term":"GSC / GA4","def":"Google Search Console and Google Analytics 4. Free, and the source of truth in every report."},{"term":"Featured snippet","def":"The answer box above the results. Usually won with a clear 40–60 word direct answer."},{"term":"Map pack","def":"The three local business results with the map. Won through Business Profile quality and proximity, not blog posts."}]} as DeepCourse;

export default course;
